patterns=[]
def card(pid,vi,ja,skill,meaning,formula,sources,tags,**kw):
 d=dict(id=pid,nameVi=vi,nameJa=ja,level='N4 nền / giao tiếp sơ cấp (ước lượng)',skill=skill,meaningVi=meaning,formula=formula,sources=sources,tags=tags,prerequisites=['Đọc kana và hiểu từ trong ví dụ; ôn thể thường/て/た khi cần'],typicalMisunderstanding=kw.get('commonMistake','Bám một từ tín hiệu mà bỏ quan hệ ý.'),reviewStrategy='Che ví dụ, tự nói lại ý rồi đổi một chi tiết; kiểm lại bằng tình huống mới sau ít nhất 3 ngày khi có câu chưa thấy.',reviewStatus='AI soạn gốc; tác giả rà ý/ngữ pháp theo nguồn 15/10/2026; chưa có QA ngôn ngữ độc lập lượt hai hay hiệu chuẩn người học.',origin='Original instructional card, not official JLPT item',estimatedMinutes=4)
 d.update(kw);patterns.append(d);return d
def pr(stem,opts,key,why):return {'stem':stem,'options':opts,'correctIndex':key,'answerVi':str(key+1)+'. '+why,'scored':False,'validation':'Author-reviewed instructional example; not independent bank item'}
grammar=[
('G01','Chủ đề và thông tin cần xác định','は／が','Nは… / Nが…',[src('095','副助詞'),src('053','格助詞')],'は nêu điều đang nói hoặc đối chiếu; が đánh dấu chủ thể, có thể xác định đáp án cho “ai/cái gì”. Không phải quy tắc cứng “cũ/mới”.','私はリンです。／私がリンです。','Câu đầu giới thiệu về tôi; câu sau xác định chính tôi là Lin trong ngữ cảnh hỏi ai là Lin.','Thay は/が máy móc theo vị trí đầu câu.','Hỏi: câu đang nói về ai, hay cần xác định chính ai?',[pr('「だれが担当ですか。」担当が自分だと答えます。',['私が担当です。','私を担当です。'],0,'が xác định người phụ trách; を không đánh dấu chủ thể ở đây.'),pr('「コーヒーは飲みますが、お茶は飲みません。」何を飲みませんか。',['コーヒー','お茶'],1,'は ở đây đối chiếu cà phê với trà, không phải phủ định cả hai.'),pr('「これは私のかばんです。」何について説明していますか。',['このかばん','明日の予定'],0,'これ chỉ chiếc túi đang nói tới; không có lịch ngày mai.')]),
('G02','Địa điểm hành động, tồn tại và hướng','に／で／へ','場所でV / 場所にNがいる・ある / 場所に・へ行く',[src('053','格助詞')],'で: nơi hành động; に: nơi tồn tại hoặc điểm đến; へ: hướng. に/へ có thể cùng đúng với đi đến, không học một khóa giả.','教室で話します。／教室に先生がいます。','Nói chuyện diễn ra ở lớp; giáo viên tồn tại ở lớp.','Dùng で với います vì đều dịch là “ở”.','Tìm động từ trước rồi chọn vai của địa điểm.',[pr('公園（　）犬がいます。',['に','で'],0,'います chỉ tồn tại, dùng に.'),pr('台所（　）料理を作ります。',['を','で'],1,'で đánh dấu nơi nấu ăn.'),pr('「駅へ行きます。」駅 là gì?',['Hướng/điểm đến','Nơi tồn tại của chìa khóa'],0,'へ hướng về ga. 駅に行きます cũng có thể đúng; không loại に máy móc.')]),
('G03','Nối lý do nhẹ nhàng','から／ので','普通形・丁寧形＋から／ので; N・ナ形容詞＋なので',[src('081','理由')],'Cả hai đều nối lý do. ので thường phù hợp khi giải thích để nhờ; から nêu lý do rõ hơn. Đây là sắc thái theo ngữ cảnh, không có cấm tuyệt đối.','電車が遅れたので、少し遅れます。／電車が遅れたから、少し遅れます。','Cùng báo trễ vì tàu; sắc thái lời giải thích khác nhẹ, không đổi sự kiện.','Nói 学生だので hoặc kết luận から luôn bất lịch sự.','Với danh từ/thể thường: 学生なので; học cả lý do và kết quả.',[pr('学生（　）、この割引が使えます。',['なので','だので'],0,'N＋なので; だので không phải cách nối chuẩn.'),pr('「熱があるので、休みます。」理由は何ですか。',['休むこと','熱があること'],1,'Phần trước ので là lý do: có sốt.'),pr('雨だから、外では練習しません。自然な言い換えは？',['雨なので、外では練習しません。','雨なのを、外では練習しません。'],0,'だから và なので đều nối lý do; なのを không nối như vậy.')]),
('G04','Kéo dài đến mốc hay hoàn tất trước hạn','まで／までに','時までV継続 / 時までにV完了',[src('053','格助詞'),JF],'まで nêu giới hạn của khoảng kéo dài; までに là hạn hoàn tất. Ví dụ hạn là khung dạy học, không phải mẹo chỉ nhìn động từ.','6時まで働きます。／6時までに連絡します。','Làm việc kéo dài đến 6 giờ; liên lạc chậm nhất lúc 6 giờ.','Dịch cả hai thành “đến” rồi bỏ に.','Vẽ một đoạn kéo dài hoặc một dấu hoàn tất trước mốc.',[pr('一枚の書類の締切は3時です。3時（　）出してください。',['までに','から'],0,'Nộp hoàn tất trước hạn, dùng までに; から là từ lúc đó.'),pr('午後1時から4時（　）働きました。',['までに','まで'],1,'Khoảng làm kéo dài từ 1 đến 4.'),pr('「5時までに電話してください。」5時は何ですか。',['Hạn gọi chậm nhất','Giờ bắt đầu nói liên tục'],0,'までに là hạn hoàn tất cuộc gọi/liên lạc, không yêu cầu gọi liên tục.')]),
('G05','Thứ tự trước và sau','前に／後で','Vる前にB / Vた後でB / Nの前に・後で',[JF],'Trong A前にB: B trước A. Trong A後でB: B sau A. Chia thể đúng dù câu chính ở quá khứ.','出かける前に鍵を確認します。／出かけた後で電話します。','Kiểm chìa khóa trước khi ra ngoài; gọi sau khi ra ngoài.','Đọc thứ tự từ trái sang phải hoặc nói 食べた前に.','Ghi A→B bằng ý nghĩa, rồi kiểm Vる trước 前に, Vた trước 後で.',[pr('寝る前に、日記を書きます。先にすることは？',['日記を書く','寝る'],0,'Viết nhật ký trước khi ngủ.'),pr('宿題を（　）後で、テレビを見ます。',['する','した'],1,'Vた後で: sau khi đã làm bài.'),pr('ご飯を食べる前に、手を洗いました。食事はいつ？',['Sau rửa tay','Trước rửa tay'],0,'Thể る trước 前に không đổi theo quá khứ của 洗いました.')]),
('G06','Đang làm và trạng thái được chuẩn bị','ている／てある','人がVている / 自動詞ている / 対象が他動詞てある',[src('044','進行'),src('045','状態'),src('046','てあります')],'ている có thể là tiến trình, thói quen hoặc trạng thái tùy động từ. てある thường nhấn trạng thái còn lại do ai cố ý làm; bài này chỉ học trường hợp cơ bản.','ドアが開いています。／ドアが開けてあります。','Cửa đang mở; cửa đã được ai mở sẵn và còn như vậy.','Cho rằng ている luôn là đang, hoặc ghép 開いてある.','Phân biệt 開く tự động từ với 開ける tha động từ; hỏi có hàm ý chuẩn bị không.',[pr('今、山本さんは電話で（　）。',['話しています','話してあります'],0,'Người đang nói: ている, không dùng kết quả chuẩn bị cho hành động nói ở đây.'),pr('「いすが並べてあります。」分かることは？',['Ghế tự di chuyển','Có người đã xếp ghế và trạng thái còn'],1,'並べる là xếp có chủ ý; てある nhấn kết quả.'),pr('「毎週、泳いでいます。」意味は？',['Thói quen mỗi tuần','Chỉ ngay giây phút hiện tại'],0,'毎週 cho biết thói quen; ている không chỉ có một nghĩa.')]),
('G07','Điều kiện: hiểu quan hệ trước khi chọn','たら／なら／と／ば','Vたら / 普通形なら / Vると / Vば',[src('083','条件')],'たら: khi/nếu việc xảy ra; なら: lấy thông tin làm tiền đề để nói tiếp; と: quan hệ thường lệ; ば: điều kiện để kết quả có thể xảy ra. Có vùng chồng lấn; không đặt câu hỏi giả rằng luôn chỉ một mẫu đúng.','駅に着いたら、電話してください。／駅へ行くなら、地図を持っていってください。','Câu đầu gọi sau khi tới; câu sau khuyên mang bản đồ trước khi đi, dựa trên dự định.','Ghi bốn nghĩa tiếng Việt rồi thay qua lại bất kể thứ tự.','Xác định điều kiện, kết quả và thứ tự; chấp nhận các cách khác nếu ngữ cảnh cho phép.',[pr('「会社に着いたら、電話してください。」電話はいつ？',['Sau khi tới công ty','Trước khi rời nhà'],0,'着いたら đặt việc tới trước cuộc gọi.'),pr('「旅行するなら、先に切符を買ってください。」切符を買うのは？',['Sau chuyến đi','Trước chuyến đi'],1,'なら nhận dự định làm tiền đề để khuyên mua vé trước.'),pr('「このつまみを右に回すと、音が大きくなります。」関係は？',['Thao tác và kết quả thường lệ','Lời mời đi ăn'],0,'と nêu kết quả máy móc; không có lời mời.')])]
