listens=[
('L01','Theo giờ mới, quyết định cuối','予定変更・最終決定',['変更','では','やっぱり','ではなく'],'A：集合は9時ですね。\nB：明日は10時に変わりました。場所は同じです。\nA：では、10時に行きます。','Tập trung đổi từ 9 sang 10 giờ, địa điểm giữ nguyên.','今の集合時間は？',['9時','10時','11時'],1,'10時に変わりました xác nhận đổi, A nhắc lại 10. Giờ đầu là nhiễu.','Gạch giờ cũ, khoanh giờ mới; đổi cả ngày/địa điểm chỉ khi nghe có nói.'),
('L02','Việc cần làm và không cần làm','指示・義務・例外',['まず','てください','なくてもいい','だけ'],'A：この二枚をコピーしてください。青い紙はコピーしなくてもいいです。\nB：白い二枚だけですね。\nA：はい。','Chỉ photo hai tờ trắng; tờ xanh không bắt buộc.','何をコピーしますか。',['青い紙だけ','全部','白い二枚'],2,'白い二枚だけ được xác nhận. なくてもいい không phải cấm vĩnh viễn.','Tự nói “ai làm gì, cái nào loại ra”; đổi một vật để kiểm hiểu.'),
('L03','Chọn theo đủ điều kiện','選択・条件',['でも','なら','両方','以内'],'A：昼ご飯、どうしますか。\nB：安くて、10分以内に食べられる店がいいです。\nA：食堂は安いけど20分かかります。そば屋は安くて5分です。\nB：では、そば屋にしましょう。','Cần rẻ và trong 10 phút; quán soba thỏa cả hai.','どこに行きますか。',['そば屋','食堂','まだ決まっていない'],0,'Không chọn chỉ theo rẻ; nhà ăn mất 20 phút nên không thỏa thời gian.','Ghi hai điều kiện bằng hai từ, kiểm từng lựa chọn rồi nghe chốt.'),
('L04','Từ chối gián tiếp và ý định','断り・意図',['ちょっと','すみません','また今度'],'A：今夜、いっしょに食事しませんか。\nB：すみません、今夜はちょっと。明日はどうですか。\nA：明日なら大丈夫です。','B từ chối tối nay và đề nghị ngày mai; đã nhận lời cho ngày mai.','Bさんは今夜、行きますか。',['行くと言った','行かないつもり','まだ返事をしていない'],1,'Trong lời mời, 今夜はちょっと là từ chối nhẹ; câu sau đề nghị hôm khác. Không phải mọi ちょっと đều từ chối.','Đổi tối nay thành cuối tuần; tự nói từ chối kèm phương án khác.'),
('L05','Lý do chính và thái độ','理由・意見・概要',['一番','実は','と思う','けれど'],'A：どうして自転車で来るんですか。\nB：電車より安いです。でも、一番の理由は体を動かしたいからです。\nA：そうなんですね。','Rẻ là một lợi ích, lý do chính là muốn vận động.','一番の理由は何ですか。',['運動したいから','駅が遠いから','安さだけが理由だから'],0,'一番の理由 chỉ mức ưu tiên. Không chọn lợi ích đầu chỉ vì nghe trước.','Tóm tắt lý do bằng một câu; kiểm từ nối trước/sau でも.'),
('L06','Đáp ngay và nối thông tin','応答・情報の統合',['もう一度','ということ','それなら'],'A：会議は2時です。資料は受付でもらってください。\nB：すみません、資料はどこでもらえばいいですか。\nA：受付です。\nB：分かりました。会議の前にもらいます。','Hỏi đúng chỗ chưa rõ: nhận tài liệu tại quầy; họp 2 giờ.','Bさんの次の行動は？',['2時に帰る','受付で資料をもらう','資料を家で作る'],1,'Thông tin giờ và nơi nhận phục vụ việc tiếp theo; không có yêu cầu tự làm tài liệu.','Tự đặt câu hỏi xác nhận một thông tin thiếu, rồi nói việc tiếp theo.')]
for pid,vi,ja,signals,dial,trans,stem,opts,key,why,rule in listens:card(pid,vi,ja,'Nghe', 'Mẫu giao tiếp quan sát để luyện hiểu, không phải thống kê tần suất JLPT.', 'Nghe câu hỏi → theo quan hệ ý → kiểm lời chốt', [EX,JF]+([src('064','断り方')] if pid=='L04' else []),['nghe','thời gian' if pid=='L01' else 'giao tiếp'],signals=signals,dialogue=dial,dialogueVi=trans,listenFor=rule,commonMistake='Bắt một từ đã nghe mà bỏ phủ định, điều kiện hoặc phần sửa sau.',correctionRule=rule,reviewStrategy='Ôn 1 phút: che chữ, nhớ ý cần tìm trong 10 giây; tự nói lại một câu và đổi một chi tiết. Nếu chưa có âm Nhật, chỉ là đọc hội thoại.',practice=[pr(stem,opts,key,why)],officialCategoryNote='Các tình huống không đồng nhất với đại mục thi. Xem ma trận chính thức kèm theo.')
reads=[
('R01','Ý chính và ý người viết','要点・筆者の意図','Tóm tắt việc người viết muốn báo/nhờ, rồi tìm một câu làm bằng chứng.','資料は受付にあります。会議の前に一部ずつ取ってください。','Người viết nhờ lấy mỗi người một bản tài liệu trước họp.','書いた人がしてほしいことは？',['資料を一部取る','受付を閉める'],0,'取ってください là yêu cầu; 受付 chỉ nơi tài liệu, không phải việc đóng quầy.','Chọn đáp án có từ giống đoạn nhưng quan hệ sai.'),
('R02','Đối chiếu lý do và bằng chứng','対比・理由・根拠','Đọc câu trước và sau しかし/でも; không cho một từ nối quyền quyết định đáp án.','この店は少し遠いです。でも、野菜が新鮮なので、毎週行きます。','Xa nhưng rau tươi nên người viết đi hằng tuần.','毎週行く理由は？',['近いから','野菜が新鮮だから'],1,'ので nối 新鮮 với việc đi; 遠い là điểm bất lợi, không phải gần.','Bỏ nửa câu sau でも hoặc lẫn nguyên nhân với kết quả.'),
('R03','Điều kiện, ngoại lệ và tra thông tin','条件・例外・情報検索','Xác định người/ngày/điều kiện trong câu hỏi rồi kiểm đúng hàng và chú thích.','店は毎日10時に開きます。ただし、月曜日は12時からです。','Ngày thường 10 giờ; riêng thứ hai 12 giờ.','月曜日、店は何時から？',['10時','12時'],1,'ただし + 月曜日 xác định ngoại lệ. 10時 là thông tin chung, sai trường hợp.','Đọc thông tin chung rồi bỏ ngoại lệ; chỉ tìm số giống nhau.'),
('R04','Tách câu và lần theo từ chỉ định','文のまとまり・指示語','Tìm vị ngữ cuối; khoanh cụm bổ nghĩa trước danh từ; tìm tiền ngữ phù hợp với これ/それ cả nghĩa lẫn phạm vi.','昨日、先生にもらった本を読みました。それは日本の料理についての本です。','Đọc quyển sách nhận từ giáo viên; それ là quyển sách, không phải giáo viên.','「それ」は何ですか。',['先生','昨日読んだ本'],1,'Văn cảnh nói quyển sách; 料理について mô tả sách. Không chọn danh từ gần nhất máy móc.','Dịch từng từ hoặc chọn tiền ngữ gần nhất bất kể nghĩa.')]
for pid,vi,ja,formula,text,trans,stem,opts,key,why,mistake in reads:card(pid,vi,ja,'Đọc',formula,formula,[EX,JF]+([src('079','V＋N')] if pid=='R04' else []),['đọc','bằng chứng'],dialogue=text,dialogueVi=trans,commonMistake=mistake,correctionRule='Gạch một cụm bằng chứng rồi nói quan hệ bằng lời mình; thử đoạn mới khi đủ sức.',practice=[pr(stem,opts,key,why)],reviewStrategy='Ôn 1 phút: che đoạn, nói lại ai–làm gì–vì sao, mở kiểm một cụm; không nhớ đáp án chữ cái.')
templates=[
('T01','Nhờ giáo viên giải thích lại','聞き返し・説明依頼','先生、【部分】がまだよく分かりません。もう一度説明していただけますか。','先生、この文の意味がまだよく分かりません。もう一度説明していただけますか。','Thưa cô/thầy, em chưa rõ nghĩa câu này, có thể giải thích lại giúp em không?','Lịch sự với giáo viên; もう一度お願いします cũng dùng để xin nhắc lại khi ngữ cảnh rõ.','先生に普通体で「説明して」と buông yêu cầu; không chỉ ra chỗ chưa hiểu.','Đổi nghĩa câu thành cách chia động từ.','A：もう少しゆっくり話していただけますか。\nB：はい。この紙に名前を書いてください。\nA：名前ですね。分かりました。','A nhờ nói chậm; B yêu cầu ghi tên; A xác nhận tên.','Đóng vai giáo viên, nói một yêu cầu ngắn. Khi tôi hỏi lại hoặc xin chậm, nói lại từng cụm; yêu cầu tôi xác nhận.'),
('T02','Báo vắng học','欠席連絡','【先生】先生、【クラス・名前】です。【日付】は【理由】のため、授業を欠席します。【確認したいこと】。','田中先生、Aクラスのリンです。今日は体調不良のため、授業を欠席します。宿題を教えていただけますか。','Báo rõ lớp/tên, vắng hôm nay vì không khỏe và hỏi bài tập. Đây là ví dụ hư cấu.','Lịch sự, tin nhắn/email ngắn. Theo quy định báo vắng của trường; không bịa lý do thật.','Chỉ nói 休みます không cho biết ai/ngày; dùng nghỉ học để xin phép nghỉ làm.','Đổi ngày và hỏi tài liệu cần xem.','A：今日は体調が悪いので、授業を休みます。\nB：分かりました。宿題はあとで送ります。\nA：ありがとうございます。','Học viên báo vắng; giáo viên sẽ gửi bài; học viên cảm ơn.','Đóng vai giáo viên nhận báo vắng, hỏi tên/lớp nếu thiếu rồi nói bài tập. Hỏi từng lượt, không tự bịa tình trạng sức khỏe tôi.'),
('T03','Xin đổi giờ ca làm','シフト変更','【相手】さん、【名前】です。【日付】のシフトを【希望時刻】からに変更していただけませんか。【理由】ためです。','店長、リンです。明日のシフトを午後5時からに変更していただけませんか。学校の予定があるためです。','Xin đổi ca ngày mai sang bắt đầu 17 giờ vì lịch học; đây là đề nghị, chưa được duyệt.','Lịch sự nơi làm việc, không phải thư kinh doanh đầy đủ. Đơn giản hơn: 変更できますか.','Nhầm から với まで; kể đề nghị như đã được đồng ý.','Đổi giờ bắt đầu và chờ quản lý đưa giờ khác.','A：明日は午後5時からに変更できますか。\nB：5時半からなら大丈夫です。\nA：では、5時半からですね。ありがとうございます。','Quản lý chỉ đồng ý 17:30, người học xác nhận giờ mới.','Đóng vai quản lý. Đề nghị một giờ khác để tôi phải xác nhận; không chấp nhận đọc nguyên câu mẫu là đã hiểu.'),
('T04','Xin nghỉ làm một buổi/ngày','休みの相談','【日付】は【理由】のため、お休みをいただけますか。必要な手続きがあれば教えてください。','来週の火曜日は学校の試験のため、お休みをいただけますか。必要な手続きがあれば教えてください。','Xin nghỉ thứ ba tuần tới vì thi ở trường và hỏi thủ tục.','Lịch sự với cấp trên; câu xin phép, không đảm bảo được nghỉ. Làm theo quy định nơi làm.','Nói 休みます như đã tự chốt khi cần xin duyệt.','Đổi ngày và lý do do bạn lựa chọn.','A：金曜日の夜、食事に行きませんか。\nB：すみません、その日は予定があります。また今度お願いします。\nA：分かりました。','Đối thoại phụ luyện từ chối lời mời lịch sự; không phải xin nghỉ.','Đóng vai đồng nghiệp mời ăn. Tôi từ chối nhẹ và có thể đề xuất hôm khác. Không coi mọi ちょっと là từ chối ngoài ngữ cảnh lời mời.'),
('T05','Xin lỗi và báo trễ','遅刻連絡','【名前】です。【理由】で、【到着見込み】。遅れてすみません。【次の確認】。','リンです。電車が遅れていて、到着は9時10分ごろになりそうです。遅れてすみません。着いたら、どこへ行けばいいですか。','Báo tàu trễ, ước khoảng 9:10 tới và hỏi đến đâu khi tới. Nếu chưa biết, nói まだ分かりません.','Lịch sự, ngắn, cung cấp thông tin thật. Không hứa giờ chắc chắn nếu chỉ ước.','Xin lỗi dài nhưng thiếu giờ ước; bịa giờ đến.','Đổi thành chưa biết giờ và xin cách xử lý.','A：電車が止まっています。到着時間はまだ分かりません。\nB：分かったら、また連絡してください。\nA：はい、分かったら連絡します。','Người nói chưa biết; người nhận yêu cầu liên lạc lại khi biết.','Đóng vai người phụ trách. Hỏi giờ đến; chấp nhận chưa biết, rồi giao một việc để tôi nhắc lại.'),
('T06','Xác nhận lịch và hỏi tiếp','予定確認','【予定】は【日時・場所】でよろしいですか。【追加の質問】。','面談は金曜日の午後3時、2番の教室でよろしいですか。何を持っていけばいいですか。','Xác nhận phỏng vấn thứ sáu 15 giờ phòng 2; hỏi mang gì.','Lịch sự. Nói đơn giản: 金曜日の3時ですね. Thân mật với bạn: 3時でいい？','Chỉ hỏi giờ nhưng bỏ ngày/địa điểm, hiểu 予定 là đã chốt mọi điều.','Đổi lịch từ thứ sáu sang thứ hai rồi hỏi thời lượng.','A：面談は3時ですね。\nB：はい、2番の教室です。\nA：何分ぐらいかかりますか。\nB：20分ぐらいです。','Xác nhận giờ, nhận nơi, hỏi tiếp thời lượng.','Đóng vai giáo viên, cho một thông tin chưa đủ để tôi hỏi tiếp; không đưa tất cả ngay.'),
('T07','Xin làm rõ chỉ dẫn','指示確認','【聞き取った内容】ということですか。【不明点】はどうすればいいですか。','この二枚をコピーするということですか。青い紙はどうすればいいですか。','Xác nhận photo hai tờ; hỏi tờ xanh xử lý ra sao.','Lịch sự nơi học/làm; Nですね là cách đơn giản hơn.','Chỉ đáp はい dù chưa rõ; hỏi lại toàn bộ thay vì chỉ chỗ thiếu.','Đổi màu giấy và số lượng.','A：この二枚をコピーしてください。\nB：二枚ですね。青い紙もコピーしますか。\nA：青い紙はコピーしなくてもいいです。\nB：分かりました。','Hai tờ cần làm, xanh không bắt buộc; không phải bị cấm photo.','Đóng vai đồng nghiệp giao một chỉ dẫn có điều kiện. Đợi tôi hỏi và nói lại, sửa tối đa hai lỗi cản nghĩa.'),
('T08','Báo vấn đề ở nơi làm','問題報告','【いつ・場所】で【問題】が起きました。今は【状況】です。どうすればいいですか。','レジのプリンターが止まりました。今は印刷できません。どうすればいいですか。','Máy in quầy thu ngân dừng, hiện chưa in được, hỏi xử lý.','Lịch sự, báo sự kiện quan sát; nếu có nguy hiểm thật, theo quy trình và người phụ trách.','Đổ lỗi cho người khác khi chưa rõ; giấu phần chưa biết.','Đổi từ máy in sang không tìm thấy tài liệu.','A：印刷できません。どうすればいいですか。\nB：まず、担当の人を呼んでください。\nA：はい。担当の人を呼びます。','Báo không in được, được yêu cầu gọi người phụ trách, tự nhắc lại.','Đóng vai đồng nghiệp: hỏi vấn đề, đưa một việc đơn giản; không tự hướng dẫn sửa máy nguy hiểm. Đợi tôi nhắc lại.'),
('T09','Nhật ký ba câu','短い日記','今日は【出来事】。 【気づき・気持ち】。次は【小さな行動】。','今日は授業のあとで買い物をしました。店員さんの説明が少し分かりました。次は自分から質問したいです。','Hôm nay đi mua sắm sau lớp; hiểu được chút lời nhân viên; lần tới muốn chủ động hỏi.','Nhật ký cá nhân: thể thường hoặc です/ます nhất quán; không cần văn kinh doanh.','Bịa “mỗi ngày học lâu”; dịch nhật ký dài làm tăng việc.','Đổi một việc đã làm thật hôm nay, tối đa ba câu.','A：今日はどうでしたか。\nB：少し疲れましたが、店で質問できました。\nA：何を聞いたんですか。\nB：値段を聞きました。','Mệt nhưng hỏi được giá; đây là trò chuyện thân thiện có đuôi lịch sự.','Hỏi tôi một việc trong ngày rồi một câu hỏi tiếp; không buộc viết dài hoặc tiết lộ việc riêng.'),
('T10','Nêu ý kiến ngắn và chưa chắc','意見・不確かさ','私は【意見】と思います。【理由】からです。まだ【不確かな点】は分かりません。','私は短い練習が続けやすいと思います。時間を取りやすいからです。長い練習の効果はまだ分かりません。','Nghĩ bài ngắn dễ duy trì vì dễ dành thời gian; chưa biết hiệu quả buổi dài. Đây là ý kiến cá nhân, không phải kết luận khoa học.','Lịch sự khi trao đổi; với bạn thân có thể bỏ です/ます nhưng giữ ý.','Nói ý kiến thành sự thật chung; gắn 思います sau thể ます.','Đổi chủ đề sang đi tàu/xe đạp, nói một điều chưa chắc.','A：この方法はどうですか。\nB：便利だと思いますが、まだよく分かりません。\nA：どの点が分かりませんか。','Nêu tiện nhưng chưa chắc, người nghe hỏi phần chưa rõ.','Hỏi ý kiến về lựa chọn học thật; chấp nhận まだ分かりません và hỏi một phần cụ thể, không ép chắc chắn.'),
('T11','Đưa lý do và ví dụ','理由・具体例','【意見】。なぜなら、【理由】からです。例えば、【具体例】。','私は通学の時間を短くしたいです。なぜなら、休む時間を増やしたいからです。例えば、近い学校なら、帰宅後に少し休めます。','Ý muốn giảm thời gian đi học, lý do nghỉ nhiều hơn, ví dụ cụ thể; chỉ là bài tập hư cấu.','Văn bài tập lịch sự; trong nói có thể nối thẳng 理由ので/から, không cần なぜなら.','Ví dụ không minh họa lý do; dùng なぜなら nhưng không kết からです.','Đổi ý kiến và giữ một ví dụ thật liên quan.','A：どうしてこの店を選んだんですか。\nB：安くて、駅に近いからです。\nA：そうなんですね。','Hỏi lý do chọn quán; đáp hai điểm liên quan.','Hỏi vì sao tôi chọn một phương án; yêu cầu một ví dụ khi lý do quá chung, không đưa sẵn đáp án.'),
('T12','Bài viết học đường ngắn','短い作文','【主題・意見】。まず、【理由1】。例えば、【具体例】。だから、【まとめ・次の行動】。','私は日本語で質問できるようになりたいです。まず、分からないことを確認したいからです。例えば、仕事の時間を聞き直せると安心です。だから、短い質問を練習します。','Chủ đề muốn hỏi bằng tiếng Nhật; lý do xác nhận điều chưa hiểu; ví dụ hỏi lại giờ làm; hành động luyện câu hỏi ngắn.','Văn bài tập kiểu です/ます; kiểm yêu cầu số chữ, chủ đề, quy định trường trước khi dùng. JLPT không thi viết trực tiếp.','Chép nguyên mẫu không thay ý; thiếu câu trả lời đúng đề; đổi thể giữa chừng.','Viết bốn câu về một việc muốn cải thiện; kiểm xem ví dụ có hỗ trợ ý không.','A：何について書きますか。\nB：仕事で使う日本語についてです。\nA：具体的な例はありますか。\nB：時間を確認する質問です。','Người học chọn chủ đề, được hỏi ví dụ cụ thể.','Đóng vai giáo viên hỗ trợ bài ngắn. Hỏi chủ đề và ví dụ từng lượt, không viết hộ toàn bài; yêu cầu tôi tự sửa một câu.')]
for pid,vi,ja,template,ex,trans,formal,mistake,exercise,dial,dialvi,role in templates:card(pid,vi,ja,'Viết / nói',vi+'; hiểu ý trước khi thay ô, không dùng như kịch bản cố định.',template,[JF,src('081','理由'),src('064','断り方')] if pid=='T04' else [JF],['viết','nói','trường','công việc'],template=template,example=ex,exampleVi=trans,formality=formal,commonMistake=mistake,exerciseVi=exercise,dialogue=dial,dialogueVi=dialvi,roleplayPrompt=role,correctionRule='Nói/viết ai–việc gì–khi nào; chờ phản hồi rồi tự xác nhận dữ kiện mới. Chỉ học câu cần dùng hôm nay.')
assert len(patterns)==29
payload={'version':'patterns-2026.10.15-v1','count':29,'patterns':patterns,'officialListeningMap':{'N4':['課題理解','ポイント理解','発話表現','即時応答'],'N3':['課題理解','ポイント理解','概要理解','発話表現','即時応答'],'N2':['課題理解','ポイント理解','概要理解','即時応答','統合理解']},'frequencyClaim':'Không có dữ liệu tần suất; các tình huống do dự án chọn để luyện, không gọi là thường ra nhất.','unscoredPracticeCount':sum(len(p.get('practice',[])) for p in patterns),'reviewLimit':'29 cards and 31 instructional examples author-reviewed against sources, not included in independently audited 80-item bank.'}
(D/'patterns.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf-8');(P/'patterns.js').write_text('window.PatternLibrary='+json.dumps(payload,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
(D/'README.md').write_text('# Thư viện mẫu\n\nMở ứng dụng → Mẫu cần dùng. 29 thẻ (7 ngữ pháp, 6 nghe, 4 đọc, 12 viết/nói), 31 câu học có hướng dẫn. Không cộng vào 80 câu kiểm định độc lập. Nguồn chỉ giải thích khái niệm, không chứng nhận mức JLPT của câu gốc. Không có thống kê tần suất.\n\nDữ liệu `patterns.json` dùng lại được; `JLPT_PRACTICE/patterns.js` là cùng dữ liệu nạp sẵn để mở local. Thẻ G01–G07 có ba bài; nghe/đọc có một bài. Khóa chỉ mở thủ công sau khi tự đáp. Mẫu N3/N2 chưa mở rộng, chỉ có ma trận dạng thi chính thức.\n\nQA: tác giả rà 29 thẻ và đáp án; chưa có lượt QA ngôn ngữ độc lập cho phụ lục. Bài mới trong thư viện chỉ dùng để học, không chấm năng lực độc lập.\n',encoding='utf-8')
print('cards',len(patterns),'instructional items',payload['unscoredPracticeCount'])
